import React from "react";
import { call, on, isDemo } from "../../api.js";
import { Markdown } from "./BuildPage.jsx";
import { Empty, PageHead, ROLE, SectionHead, Status, TraceButton, fmtMoney } from "./shared.jsx";
import "./cfo.css";
// Creator CFO: what each mod cost to make (from the agents' recorded usage), what the next one will cost, and a CFO
// that answers with the creator's cfo.ai model over its MCP server, and writes back to it when asked.
const pct = (n) => (n == null ? "—" : `${Math.round(n * 100)}%`);
const money = (n) => (n == null ? "—" : n > 0 && n < 0.01 ? "<$0.01" : fmtMoney(n));
// Questions that need cfo.ai: the creator's own plan, scenarios, alerts and a model that keeps the numbers.
function suggestions(b) {
  const t = b?.totals;
  const top = b?.mods.find((m) => m.status === "passed" && m.costComplete && m.cost > 0 && !m.remix);
  return [
    { label: "Sync my build costs", q: "Record my Benana build costs in cfo.ai as a Benana table (one row per mod: build cost, rework, attempts, status) so they stay in my model." },
    top && { label: `Price ${top.name}`, q: `What should I charge for ${top.name} on the Benana marketplace? It cost ${money(top.cost)} to build in ${top.attempts} attempt${top.attempts === 1 ? "" : "s"}. Use my cfo.ai plan's margins and tell me the break-even.` },
    t && { label: "10 mods a month?", q: `Build a Benana scenario in cfo.ai: if I ship 10 mods a month at my current ${money(t.costPerVerifiedMod)} per verified mod, what is my monthly build spend, and how many $1.99 sales a month cover it?` },
    t?.reworkShare > 0.05 && { label: "Cost of rework", q: `${pct(t.reworkShare)} of my build spend (${money(t.rework)}) went to fix attempts. What does that cost me per year at my current pace, and is it worth cutting?` },
    { label: "Alert me on overspend", q: "Set up a weekly Benana alert in cfo.ai that warns me if my cost per verified mod goes above $1.00." },
  ].filter(Boolean);
}
export default function CfoPage({ mods }) {
  const [books, setBooks] = React.useState(undefined);
  const [cfo, setCfo] = React.useState(null);
  const [error, setError] = React.useState("");
  const [question, setQuestion] = React.useState("");
  const [live, setLive] = React.useState(null); // { id, question, events, entry? }
  const [history, setHistory] = React.useState([]);
  const [exported, setExported] = React.useState(null);
  const askRef = React.useRef(null);
  const version = mods.map((m) => `${m.id}:${m.updatedAt || 0}`).join(",");
  React.useEffect(() => {
    setBooks(undefined);
    call("cfo:books").then(setBooks).catch((e) => { setBooks(null); setError(e.message); });
  }, [version]);
